import React, { useState, useEffect } from 'react';
import { DataTable } from 'primereact/datatable';
import { Column } from 'primereact/column';
import { ProductService } from './service/ProductService';
import { InputSwitch } from 'primereact/inputswitch';
import { setSelectedCellContext } from '../../../../../../../src/scripts/passthrough.js';

export default function CellSelectionSingle() {
    const [products, setProducts] = useState([]);
    const [selectedCell, setSelectedCell] = useState(null);
    const [metaKey, setMetaKey] = useState(true);

    useEffect(() => {
        ProductService.getProductsMini().then((data) => setProducts(data));
    }, []);

    return (
        <>
            <div className="fxb fvc gp3 fsb mgb5">
                <InputSwitch inputId="input-metakey" checked={metaKey} onChange={(e) => setMetaKey(e.value)} />
                <label htmlFor="input-metakey">MetaKey</label>
            </div>
            <DataTable
                value={products}
                cellSelection
                selectionMode="single"
                selection={selectedCell}
                onSelectionChange={(e) => {
                    setSelectedCell(e.value);
                    setSelectedCellContext(e.value);
                }}
                metaKeySelection={metaKey}
                tableStyle={{ minWidth: '50rem' }}
            >
                <Column field="code" header="Code"></Column>
                <Column field="name" header="Name"></Column>
                <Column field="category" header="Category"></Column>
                <Column field="quantity" header="Quantity"></Column>
            </DataTable>
        </>
    );
}